using CodeAssist.Core;
namespace CodeAssist.Core.Tests;
public class FinalFeatureTests
{
 [Fact]public void ReordersDeclarationAndCallLists(){var decl="int Mix(int first, int second);";var c=CppDocumentTransforms.ReorderParameters(decl,4,new[]{1,0},true);Assert.Equal("int Mix(int second, int first);",PluginEdits.Apply(decl,new[]{c}));var call="Mix(One(1, 2), 3)";var e=CppDocumentTransforms.ReorderParameters(call,0,new[]{1,0},false);Assert.Equal("Mix(3, One(1, 2))",PluginEdits.Apply(call,new[]{e}));}
 [Fact]public void ReorderingRefusesInvalidOrdersAndDefaults(){Assert.Throws<ArgumentException>(()=>CppDocumentTransforms.ReorderParameters("void F(int a, int b);",5,new[]{0,0},true));Assert.Throws<ArgumentException>(()=>CppDocumentTransforms.ReorderParameters("void F(int a, int b=1);",5,new[]{1,0},true));Assert.Throws<NotSupportedException>(()=>CppDocumentTransforms.ReorderParameters("&Function",1,new[]{0},false));}
 [Fact]public void InstanceConversionPreservesAutomaticStorage(){var text="void F() { Widget value; value.Run(); }";var start=text.IndexOf("Widget");var result=CppDocumentTransforms.ConvertLocalPointer(text,start,"Widget value;".Length);Assert.Contains("Widget valueStorage;",result);Assert.Contains("Widget* value = &valueStorage;",result);Assert.Contains("value->Run();",result);Assert.DoesNotContain("new Widget",result);}
 [Fact]public void PointerConversionRemovesDirectAllocation(){var text="void F() { Widget* value = new Widget(); value->Run(); }";var start=text.IndexOf("Widget");var result=CppDocumentTransforms.ConvertLocalPointer(text,start,"Widget* value = new Widget();".Length);Assert.Contains("Widget value{};",result);Assert.Contains("value.Run();",result);}
 [Fact]public void PointerEscapeRejectsEntireTransform(){var text="void F() { Widget value; Consume(value); }";Assert.Throws<NotSupportedException>(()=>CppDocumentTransforms.ConvertLocalPointer(text,text.IndexOf("Widget"),"Widget value;".Length));}
 [Fact]public void ExtractsGlobalVoidHelperWithExplicitParameters(){var text="void Work(int& value, int count) {\n    value += count;\n}\n";var start=text.IndexOf("value +=");var changed=CppDocumentTransforms.ExtractGlobalMethod(text,start,"value += count;".Length,"void Extracted(int& value, int count)");Assert.StartsWith("void Extracted(int& value, int count)",changed);Assert.Contains("Extracted(value, count);",changed);}
 [Fact]public void ExtractionRejectsControlFlowAndNewLocals(){foreach(var selected in new[]{"return;","int value = 2;"}){var text="void Work() { "+selected+" }";Assert.Throws<NotSupportedException>(()=>CppDocumentTransforms.ExtractGlobalMethod(text,text.IndexOf(selected),selected.Length,"void Extracted()"));}}
 [Fact]public void PluginEditsCheckBoundsAndOverlap(){Assert.Equal("aXc",PluginEdits.Apply("abc",new[]{new EditorTextChange(1,1,"X",0,0)}));Assert.Throws<ArgumentException>(()=>PluginEdits.Apply("abc",new[]{new EditorTextChange(1,2,"",0,0),new EditorTextChange(2,1,"",0,0)}));}
 [Theory][InlineData("bool enabled = tr", "true")][InlineData("Widget* actor = nu", "nullptr")]
 public void ExpectedTypeSuggestionsUseDeclarationContext(string text,string expected){Assert.Contains(expected,SmartSuggestions.At(text,text.Length));}
 [Fact]public void CommentsDoNotCreateExpectedTypeSuggestions(){var text="// bool enabled = ";Assert.Empty(SmartSuggestions.At(text,text.Length));}
 [Fact]public void MethodTemplateChangesGeneratedBody(){var output=CppRefactoring.CreateImplementation("int Value();","Widget",bodyTemplate:"    return 42; // $MethodName$")!;Assert.Contains("return 42; // Value",output);Assert.DoesNotContain("Not implemented",output);}
}
